manifest=json.load((root/'content/photo-manifest.json').open());photos={}
for photo in manifest['assets']:
 assert photo['verified_subject'] and photo['visually_inspected']
 path=assets/photo['filename'];assert path.is_file()
 photos[photo['id']]={k:photo[k] for k in ['id','author','license','license_url','source_page_url','alt_de','width','height','transformations_de']};photos[photo['id']]['src']='/world/'+photo['filename']
# Remove filesystem paths and ephemeral web references from the public photo-credit record.
(root/'public/world/photo-credits.json').write_text(json.dumps({'checked_at':'2026-10-07','assets':list(photos.values())},ensure_ascii=False,indent=2))
(root/'app/world-photos.json').write_text(json.dumps(photos,ensure_ascii=False,separators=(',',':')))
ids={t['id'] for t in topics};assert len(ids)==len(topics)
for t in topics:
 t['related']=[id for id in t['related'] if id in ids and id!=t['id']]
 if t.get('image') is None:t.pop('image',None)
 assert not t.get('image') or t['image'] in photos,t['id']
 assert t['sources'] and t['question']['answers'][t['question']['correct']]
 assert len(set(t['question']['answers']))==3,t['id']
 for l in t['locations']:assert abs(l['lat'])<=90 and abs(l['lon'])<=180
(root/'app/world-catalog.json').write_text(json.dumps(topics,ensure_ascii=False,separators=(',',':')))
index=[]
for t in topics:
 x={k:t[k] for k in ['id','category','title','intro','aliases','locations']}
 if t.get('image'):x['image']=t['image']
 if t.get('model'):x['model']=t['model']
 if t.get('animal'):
  for k in ['group','habitat','continent']:x[k]=t['animal'][k]
 if t.get('history'):
  for k in ['year','era','sensitive']:x[k]=t['history'][k]
 index.append(x)
(root/'app/world-index.json').write_text(json.dumps(index,ensure_ascii=False,separators=(',',':')))
print('Curated topics:',len(topics),{c:sum(t['category']==c for t in topics) for c in {t['category'] for t in topics}},'photos:',len(photos))
